import{_ as t,c as a,o,aj as n}from"./chunks/framework.CSpjyewb.js";const c=JSON.parse('{"title":"Thalamus has been accepted into the NeoNephos Foundation","description":"","frontmatter":{"title":"Thalamus has been accepted into the NeoNephos Foundation","date":"2026-11-18","banner":"assets/blog/20261118_thalamus_new_project.svg","authors":["neonephos-team"],"tags":["2026","news","projects"],"published":true,"sidebar":false,"aside":false,"prev":false,"next":false,"layout":"BlogEntryThemeComponent"},"headers":[],"relativePath":"blog/20261118_thalamus_new_project.md","filePath":"blog/20261118_thalamus_new_project.md"}'),r={name:"blog/20261118_thalamus_new_project.md"};function s(i,e,h,l,d,p){return o(),a("div",null,e[0]||(e[0]=[n('<h1 id="thalamus-has-been-accepted-into-the-neonephos-foundation" tabindex="-1">Thalamus has been accepted into the NeoNephos Foundation <a class="header-anchor" href="#thalamus-has-been-accepted-into-the-neonephos-foundation" aria-label="Permalink to &quot;Thalamus has been accepted into the NeoNephos Foundation&quot;">​</a></h1><p>We are proud to announce the addition of <a href="https://cobaltcore-dev.github.io/thalamus/v0.2.0/" target="_blank" rel="noreferrer">Thalamus</a> into NeoNephos! The interested reader may recall that Thalamus was previously <a href="https://github.com/cobaltcore-dev/thalamus/blob/main/CHARTER.md" target="_blank" rel="noreferrer">a part of our CobaltCore project</a>. However, it has outgrown its host and is now a dedicated NNF project along with all the benefits and responsibilities that come with it.</p><p>In <a href="https://cobaltcore-dev.github.io/thalamus/v0.2.0/" target="_blank" rel="noreferrer">their own words</a>:</p><blockquote><p>The mission of Thalamus is to provide a vendor-neutral, Kubernetes-native inference service for sovereign LLM deployments, ensuring that model weights, prompts, and context remain protected and within the deployment perimeter. Thalamus integrates natively with CobaltCore, Greenhouse, and the broader NeoNephos ecosystem, and supports Nvidia, AMD, and Intel infrastructure.</p></blockquote><p>But what is better than words? A video! <a href="https://www.youtube.com/watch?v=ugDZdKZ0iAg&amp;t=2s" target="_blank" rel="noreferrer">Jump straight into September&#39;s TAC presentation</a> to see a detailed demonstration of Thalamus and why it is deserving of being its own standalone project. If you are old-school enough to prefer text (or you have a limited data limit) you can still <a href="https://cobaltcore-dev.github.io/thalamus/v0.2.0/" target="_blank" rel="noreferrer">review their website</a>. So no excuses, get acquainted with Thalamus now!</p><p>On a more general note, the NeoNephos Foundation is happy to have supported Thalamus into becoming its own project. The foundation always lends its ear to the desires of the projects for further support or independence. We believe the entire topic of sovereign LLM is a great asset to our mission of <code>making cloud-native sovereign</code> and are happy to welcome the team aboard!</p>',6)]))}const m=t(r,[["render",s]]);export{c as __pageData,m as default};
